// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        address depositor = makeAddr("depositor");
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool dOk,) = address(c).call{value: amount}("");
        assertTrue(dOk);
        uint256 ownerBefore = address(this).balance;
        vm.prank(address(this));
        c.withdrawAll();
        assertTrue(address(this).balance > ownerBefore, "owner must gain funds from withdrawAll");
    }
}
